promql:
(
  node_sockstat_TCP_tw * on(instance) group_left(node) (
    node_sockstat_TCP_alloc
  )
) - ignoring(node) group_left instance(
  node_sockstat_TCP_tw offset 1d
  * on(instance) group_left(node) (
    node_sockstat_TCP_alloc offset 1d
  )
)

(
  node_cpu_seconds_total{instance="k8s-node1"} / ignoring(mode) sum(node_cpu_seconds_total) * 100
) or (
  node_cpu_seconds_total{instance="k8s-node2"} / ignoring(mode) sum(node_cpu_seconds_total) * 100
) * on(instance) group_left machine_cpu_cores > 8 and machine_cpu_physical_cores > 8

sum by (node) (
  sum_over_time(node_network_receive_drop_total{device="ens160"}[10m] on (instance) group_left(node) ) on (pod) group_right(service)
)

sum by (pod)(
  (
    rate(container_network_receive_bytes_total[5m]) > 2 * rate(container_network_transmit_bytes_total[5m])
  )
  and
  (
    (
      rate(container_fs_reads_bytes_total[5m]) + rate(container_fs_writes_bytes_total[5m])
    ) > 200 * 1024
  )
  unless
  (
    rate(node_disk_io_time_seconds_total[5m]) < 1e-8
  )
)

(
  histogram_quantile(0.9, sum by (le) (rate(traces_spanmetrics_latency_bucket{service="ts-travel-service", span_name="POST /api/v1/travelservice/trips"}[5m])))
)
- (
  histogram_quantile(0.9, sum by (le) (rate(traces_spanmetrics_latency_bucket{service="ts-travel-service", span_name="POST /api/v1/travelservice/trips"} offset 1d)[5m]))
)

(
  irate(node_udp_queues{queue="tx", instance="10.176.122.151:9100"}[1h])
  - 
  node_udp_queues{queue="tx", instance="10.176.122.151:9100"}
)
+
(
  irate(node_udp_queues{queue="tx", instance="10.176.122.152:9100"}[1h])
  - 
  node_udp_queues{queue="tx", instance="10.176.122.152:9100"}
)

# Filesystem usage and limits for all containers of ts-payment-service on node k8s-node2
container_fs_limit_bytes{container="ts-payment-service", node="k8s-node2"}
+
container_fs_usage_bytes{container="ts-payment-service", node="k8s-node2"}
-
node_filesystem_free_bytes{instance="10.176.122.152:9100"}

# Calculate free space left
node_filesystem_free_bytes{instance="10.176.122.152:9100"} - ignoring(container, node)(
  container_fs_usage_bytes{container="ts-payment-service", node="k8s-node2"}
  -
  container_fs_limit_bytes{container="ts-payment-service", node="k8s-node2"}
)
